'use strict';
const crypto=require('crypto'),{catalogue}=require('./vocabulary-contract');
const canonical=id=>typeof id==='string'&&/^vocabulary:[1-9][0-9]{0,9}$/.test(id)&&Number(id.split(':')[1])<=2147483647;
function ordered(v){if(Array.isArray(v))return v.map(ordered);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,ordered(v[k])]));return v;}
const hash=v=>crypto.createHash('sha256').update(JSON.stringify(ordered(v))).digest('hex');
function entry(e){if(!e||!canonical(e.id)||typeof e.headword!=='string'||!e.headword.trim()||e.headword.length>255||typeof e.lemma!=='string'||e.lemma.length>255||!Array.isArray(e.meanings)||!e.meanings.length||e.meanings.some(m=>typeof m.text!=='string'||m.text.length>1000)||typeof e.learningEnabled!=='boolean'||!([...catalogue.levels,null].includes(e.primaryLevel)))throw Error('Invalid local vocabulary entry');for(const [field,group]of [['themeIds','themes'],['grammarIds','grammar'],['wordTypeIds','types']])if(!Array.isArray(e[field])||e[field].some(code=>!Object.hasOwn(catalogue[group],code))||new Set(e[field]).size!==e[field].length)throw Error('Invalid local '+field);if(e.learningEnabled&&(!e.primaryLevel||!e.wordTypeIds.length||!e.themeIds.length))throw Error('Enabled vocabulary has incomplete classification');if(JSON.stringify(e).length>64000)throw Error('Vocabulary entry too large');return e;}
function create(entries,metadata){const data={format:1,metadata,entries:[...entries].sort((a,b)=>Number(a.id.split(':')[1])-Number(b.id.split(':')[1]))};const result={...data,revision:hash(data)};validate(result);return result;}
function validate(bundle){if(!bundle||bundle.format!==1||!Array.isArray(bundle.entries)||!bundle.entries.length||bundle.entries.length>100000||!bundle.metadata||!/^[a-f0-9]{64}$/.test(bundle.metadata.sourceHash||'')||bundle.metadata.sourceEntryCount!==bundle.entries.length)throw Error('Invalid or incomplete local vocabulary bundle');const ids=new Set();for(const e of bundle.entries){entry(e);if(ids.has(e.id))throw Error('Duplicate canonical vocabulary ID');ids.add(e.id);}if(bundle.revision!==hash({format:bundle.format,metadata:bundle.metadata,entries:bundle.entries}))throw Error('Vocabulary bundle checksum mismatch');return bundle;}
function searchText(e){const strings=[];function walk(value){if(typeof value==='string')strings.push(value);else if(Array.isArray(value))value.forEach(walk);else if(value&&typeof value==='object')Object.values(value).forEach(walk);}walk([e.headword,e.displayHeadword,e.lemma,e.meanings.map(m=>m.text),e.article,e.plural,e.verbForms,e.adjectiveForms,e.learningForms]);return [...new Set(strings)].join(' ').normalize('NFC').toLocaleLowerCase('de');}
module.exports={canonical,hash,entry,create,validate,searchText};
